// The only place to configure this workflow.
const SUPABASE_URL = '';   // TODO: https://<project>.supabase.co
const CHAT_ID = '';        // TODO: chat where drafts are reviewed
const APPROVAL_TIMEOUT_HOURS = 24;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');
if (!CHAT_ID) throw new Error('CHAT_ID is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');
return [{
  json: {
    chatId: CHAT_ID,
    approvalTimeoutHours: APPROVAL_TIMEOUT_HOURS,
    productsUrl: base + '/rest/v1/changelog_sources?enabled=eq.true',
    draftsUrl: base + '/rest/v1/post_drafts',
  },
}];

// Flattens each product's changelog into entries. Products are rows: url, dot path to
// the array, and a field map. GitHub's releases API needs no map, its default field
// names are already handled below.
//
// Responses pair with product rows by position, which is why the fetch node continues
// on error: a failed product must still emit an item.
const get = (obj, path) => {
  const keys = String(path || '').split('.').filter(Boolean);
  if (!keys.length) return undefined;
  return keys.reduce((acc, key) => (acc === null || acc === undefined ? undefined : acc[key]), obj);
};
const text = (x) => (x === null || x === undefined ? '' : String(x));

const products = $('Load products').all().map((i) => i.json);
const fetched = $input.all();

const entries = [];
for (let idx = 0; idx < fetched.length; idx++) {
  const json = fetched[idx].json || {};
  const product = products[idx];
  if (!product) continue;

  const rawList = get(json, product.items_path) ?? (Array.isArray(json) ? json : json.items ?? json.releases);
  const list = Array.isArray(rawList) ? rawList : rawList ? [rawList] : [];
  const map = product.field_map || {};

  for (const raw of list) {
    if (!raw || typeof raw !== 'object') continue;
    if (raw.draft === true) continue;   // unpublished GitHub release

    const id = text(get(raw, map.id) ?? raw.id ?? raw.tag_name ?? raw.version);
    const title = text(get(raw, map.title) ?? raw.name ?? raw.title ?? raw.tag_name).trim();
    if (!id || !title) continue;

    const body = text(get(raw, map.body) ?? raw.body ?? raw.description ?? raw.notes)
      .replace(/\r/g, '').trim();

    entries.push({
      id: 'changelog:' + product.product + ':' + id,
      product: product.product,
      title,
      url: text(get(raw, map.url) ?? raw.html_url ?? raw.url ?? raw.link) || null,
      published_at: raw.published_at || raw.created_at || raw.date || null,
      body: body.slice(0, 6000),
    });
  }
}

const cfg = $('Config').first().json;
return [{
  json: {
    source: 'changelog',
    key_field: 'id',
    items: entries,
    chatId: cfg.chatId,
    approvalTimeoutHours: cfg.approvalTimeoutHours,
    draftsUrl: cfg.draftsUrl,
  },
}];

// First model call: which of these entries is worth telling anyone about.
const dedup = $input.first().json || {};
const state = $('Normalise entries').first().json;
const items = Array.isArray(dedup.new_items) ? dedup.new_items : [];

const list = items.map((e) => [
  'id: ' + e.id,
  'product: ' + e.product,
  'title: ' + e.title,
  'url: ' + (e.url || 'none'),
  'notes:\n' + e.body,
].join('\n')).join('\n\n---\n\n');

return [{
  json: {
    ...state,
    entries: items,
    count: items.length,
    system: 'You find things in a product changelog that a customer would care about.'
      + ' Most changelog entries are not worth a post. You never invent evidence:'
      + ' evidence_quote must be copied verbatim from the entry, and it is checked.',
    user: 'For each entry decide whether it is worth telling users about. Skip refactors,'
      + ' dependency bumps, CI changes and internal cleanups entirely. Return one occasion'
      + ' per entry that qualifies, and nothing for the ones that do not.\n\n' + list,
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['occasions'],
      properties: {
        occasions: {
          type: 'array',
          items: {
            type: 'object',
            required: ['entry_id', 'headline', 'evidence_quote', 'audience_value'],
            properties: {
              entry_id: { type: 'string' },
              headline: { type: 'string' },
              evidence_quote: { type: 'string' },
              audience_value: { type: 'string' },
            },
          },
        },
      },
    },
  },
}];

// Same rule as the funding radar: a claim without a verbatim quote from the entry is
// dropped, not softened. This is what makes "no post without a source" true at the
// occasion stage rather than only at the draft stage.
const llm = $input.first().json || {};
const state = $('Build occasion request').first().json;

const byId = new Map(state.entries.map((e) => [e.id, e]));
const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();

const raw = llm.ok && llm.data && Array.isArray(llm.data.occasions) ? llm.data.occasions : [];

const occasions = [];
let rejected = 0;
for (const o of raw) {
  const entry = byId.get(o.entry_id);
  if (!entry) { rejected++; continue; }               // hallucinated entry id
  const quote = String(o.evidence_quote || '').trim();
  const haystack = norm(entry.title + ' ' + entry.body);
  if (quote.length < 12 || !haystack.includes(norm(quote))) { rejected++; continue; }
  if (!entry.url) { rejected++; continue; }           // no source url, no post

  occasions.push({
    entry_id: entry.id,
    product: entry.product,
    headline: String(o.headline || '').trim(),
    audience_value: String(o.audience_value || '').trim(),
    evidence: quote,
    source_url: entry.url,
    entry_title: entry.title,
    entry_body: entry.body,
  });
}

return [{
  json: {
    ...state,
    occasions,
    occasionCount: occasions.length,
    rejectedOccasions: rejected,
    consideredEntries: state.count,
    degraded: !llm.ok,
  },
}];

// Second model call: two drafts per occasion. The source url is not asked of the model,
// it is carried from the entry, so a draft cannot end up pointing at an invented link.
const state = $input.first().json;

const list = state.occasions.map((o) => [
  'occasion_id: ' + o.entry_id,
  'product: ' + o.product,
  'headline: ' + o.headline,
  'why users care: ' + o.audience_value,
  'evidence: ' + o.evidence,
].join('\n')).join('\n\n---\n\n');

return [{
  json: {
    ...state,
    system: 'You draft short product update posts. You write plainly, never hype, never'
      + ' promise dates, and never claim anything the evidence does not support.',
    user: 'For each occasion write two drafts, one for a short-form feed and one for a'
      + ' longer professional feed. Do not include links: they are added afterwards.'
      + ' Keep the short one under 280 characters.\n\n' + list,
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['drafts'],
      properties: {
        drafts: {
          type: 'array',
          items: {
            type: 'object',
            required: ['occasion_id', 'platform', 'text'],
            properties: {
              occasion_id: { type: 'string' },
              platform: { type: 'string', enum: ['short', 'long'] },
              text: { type: 'string' },
              cta: { type: 'string' },
            },
          },
        },
      },
    },
  },
}];

// Assembles the rows and the text a human reviews. Rows are built here, before the gate,
// so that approval is the only thing standing between them and the queue: nothing is
// written on the way in.
const llm = $input.first().json || {};
const state = $('Build drafts request').first().json;

const byId = new Map(state.occasions.map((o) => [o.entry_id, o]));
const drafts = llm.ok && llm.data && Array.isArray(llm.data.drafts) ? llm.data.drafts : [];

const rows = [];
for (const d of drafts) {
  const o = byId.get(d.occasion_id);
  if (!o) continue;                        // a draft for an occasion that does not exist
  const body = String(d.text || '').trim();
  if (!body) continue;

  rows.push({
    product: o.product,
    occasion: o.headline,
    platform: d.platform === 'long' ? 'long' : 'short',
    text: body,
    cta: String(d.cta || '').trim() || null,
    // Carried from the entry, never from the model.
    source_url: o.source_url,
    evidence: o.evidence,
    status: 'ready',
  });
}

const preview = rows.map((r, i) =>
  (i + 1) + '. [' + r.platform + '] ' + r.occasion + '\n' + r.text + '\n' + r.source_url
).join('\n\n');

return [{
  json: {
    ...state,
    rows,
    draftCount: rows.length,
    title: rows.length + ' post draft' + (rows.length === 1 ? '' : 's') + ' for review',
    body: preview || 'No drafts were produced.',
    source: 'changelog-to-posts',
    chat_id: state.chatId,
    timeout_hours: state.approvalTimeoutHours,
    draftsDegraded: !llm.ok,
  },
}];

// Runs only on the approved branch. Stamps the approval id onto every row so a queued
// draft can always be traced back to the decision that let it through.
const decision = $input.first().json || {};
const state = $('Prepare approval').first().json;

const rows = state.rows.map((r) => ({ ...r, approval_id: decision.request_id || null }));

return [{
  json: {
    rows,
    stored: rows.length,
    decision: decision.decision,
    approvalId: decision.request_id || null,
    draftsUrl: state.draftsUrl,
  },
}];
